package mock_validator
import("context";"crypto";"crypto/rand";"crypto/rsa";"crypto/sha256";"crypto/tls";"crypto/x509";"crypto/x509/pkix";"encoding/pem";"fmt";"math/big";"net";"time";"github.com/pion/dtls/v2";"github.com/TamilSelvam22112003/Nls-NetOS-v0.1.2/prototype/NetOS-v0.1.0/internal/protocol")
// Server is a runnable fake Validator for tests.
type Server struct{Addr,Organization string;AllowedSerials map[string]bool;InvalidSignature,ExpireClientCert bool;RootPEM []byte;root *x509.Certificate;rootKey *rsa.PrivateKey;listener net.Listener}
// New generates a self-signed root CA and configures the validator organization.
func New(org string)(*Server,error){k,e:=rsa.GenerateKey(rand.Reader,2048);if e!=nil{return nil,fmt.Errorf("root key: %w",e)};n,_:=rand.Int(rand.Reader,new(big.Int).Lsh(big.NewInt(1),128));t:=&x509.Certificate{SerialNumber:n,Subject:pkix.Name{CommonName:"Mock Validator Root",Organization:[]string{org}},NotBefore:time.Now().Add(-time.Minute),NotAfter:time.Now().Add(time.Hour),IsCA:true,BasicConstraintsValid:true,KeyUsage:x509.KeyUsageCertSign|x509.KeyUsageDigitalSignature};d,e:=x509.CreateCertificate(rand.Reader,t,t,&k.PublicKey,k);if e!=nil{return nil,fmt.Errorf("root certificate: %w",e)};return &Server{Organization:org,AllowedSerials:map[string]bool{},RootPEM:pem.EncodeToMemory(&pem.Block{Type:"CERTIFICATE",Bytes:d}),root:t,rootKey:k},nil}
// Start runs the DTLS fake Validator until ctx is canceled.
func(s *Server)Start(ctx context.Context)error{cert,key,e:=s.serverCertificate();if e!=nil{return e};l,e:=dtls.Listen("udp",&net.UDPAddr{IP:net.ParseIP("127.0.0.1"),Port:0},&dtls.Config{Certificates:[]tls.Certificate{{Certificate:[][]byte{cert.Raw},PrivateKey:key}},ClientAuth:dtls.RequireAnyClientCert});if e!=nil{return fmt.Errorf("listen mock validator: %w",e)};s.listener=l;s.Addr=l.Addr().String();go func(){<-ctx.Done();_ = l.Close()}();for{c,e:=l.Accept();if e!=nil{if ctx.Err()!=nil{return nil};continue};go s.handle(c)}}
// Close stops the mock validator.
func(s *Server)Close()error{if s.listener!=nil{if e:=s.listener.Close();e!=nil{return fmt.Errorf("close mock validator: %w",e)}};return nil}
func(s *Server)serverCertificate()(*x509.Certificate,*rsa.PrivateKey,error){k,e:=rsa.GenerateKey(rand.Reader,2048);if e!=nil{return nil,nil,e};n,_:=rand.Int(rand.Reader,new(big.Int).Lsh(big.NewInt(1),128));t:=&x509.Certificate{SerialNumber:n,Subject:pkix.Name{CommonName:"Mock Validator",Organization:[]string{s.Organization}},NotBefore:time.Now().Add(-time.Minute),NotAfter:time.Now().Add(time.Hour),KeyUsage:x509.KeyUsageDigitalSignature|x509.KeyUsageKeyEncipherment,ExtKeyUsage:[]x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}};d,e:=x509.CreateCertificate(rand.Reader,t,s.root,&k.PublicKey,s.rootKey);if e!=nil{return nil,nil,e};c,e:=x509.ParseCertificate(d);return c,k,e}
func(s *Server)handle(c net.Conn){defer c.Close();n:=make([]byte,32);if _,e:=rand.Read(n);e!=nil{return};codec:=protocol.Codec{};b,_:=codec.Encode(protocol.Message{Type:protocol.MessageChallenge,Fields:map[protocol.TLVType][]byte{protocol.FieldNonce:n}});if _,e:=c.Write(b);e!=nil{return};m,e:=codec.Decode(c);if e!=nil||m.Type!=protocol.MessageResponse{return};p,_:=pem.Decode(m.Fields[protocol.FieldBoardCert]);if p==nil{return};cert,e:=x509.ParseCertificate(p.Bytes);if e!=nil{return};serial:=string(m.Fields[protocol.FieldSerial]);if cert.Subject.SerialNumber!=serial||s.ExpireClientCert||time.Now().After(cert.NotAfter)||time.Now().Before(cert.NotBefore)||(len(s.AllowedSerials)>0&&!s.AllowedSerials[serial]){s.reject(c,"serial/certificate rejected");return};pub,ok:=cert.PublicKey.(*rsa.PublicKey);if !ok{return};h:=sha256.Sum256(n);sig:=m.Fields[protocol.FieldSignature];if s.InvalidSignature&&len(sig)>0{sig=append([]byte(nil),sig...);sig[0]^=0xff};if e=rsa.VerifyPSS(pub,crypto.SHA256,h[:],sig,&rsa.PSSOptions{SaltLength:32,Hash:crypto.SHA256});e!=nil{s.reject(c,"invalid signature");return};b,_=codec.Encode(protocol.Message{Type:protocol.MessageControllers,Fields:map[protocol.TLVType][]byte{protocol.FieldControllers:[]byte("controller=127.0.0.1:8443\nmanager=127.0.0.1:9443")}});_,_=c.Write(b)}
func(s *Server)reject(c net.Conn,reason string){b,_:=(protocol.Codec{}).Encode(protocol.Message{Type:protocol.MessageError,Fields:map[protocol.TLVType][]byte{protocol.FieldError:[]byte(reason)}});_,_=c.Write(b)}
